  add({ product: 'Uvrel bottle brush', category: 'unnecessary_refusal', sources: [{ text: 'Uvrel bottle brush total length: 32 cm.' }], question: 'What is the total length of the Uvrel bottle brush?', answer: 'I cannot give the total length based on the supplied text.', axes: unnecessary(), dispositions: ['repair'], rationale: 'The named total length is explicitly supplied, so the refusal is unnecessary despite containing no false product assertion.' });
